trait Animal {
    fn speak(&self) -> String;
}

struct Dog;
struct Cat;

impl Animal for Dog {
    fn speak(&self) -> String { "woof".to_string() }
}

impl Animal for Cat {
    fn speak(&self) -> String { "meow".to_string() }
}

fn main() {
    let mut animals: Vec<Animal> = Vec::new();
    animals.push(Dog);
    animals.push(Cat);
    for a in animals {
        println!("{}", a.speak());
    }
}
